CREATE TABLE IF NOT EXISTS hospital_specialty_clinics(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),specialty text NOT NULL CHECK(specialty IN ('skin','eecp','physio')),name text NOT NULL,status text NOT NULL DEFAULT 'active',settings jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,specialty));
CREATE TABLE IF NOT EXISTS hospital_specialty_appointments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),specialty text NOT NULL CHECK(specialty IN ('skin','eecp','physio')),patient_id uuid NOT NULL REFERENCES hospital_patients(id),provider_user_id uuid REFERENCES users(id),starts_at timestamptz NOT NULL,ends_at timestamptz,appointment_type text,reason text,status text NOT NULL DEFAULT 'requested',notes text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS hospital_specialty_billing_packages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),specialty text NOT NULL CHECK(specialty IN ('skin','eecp','physio')),code text NOT NULL,name text NOT NULL,description text,sessions integer NOT NULL DEFAULT 1,price numeric(14,2) NOT NULL DEFAULT 0 CHECK(price>=0),active boolean NOT NULL DEFAULT true,UNIQUE(tenant_id,specialty,code));
CREATE TABLE IF NOT EXISTS hospital_specialty_invoices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),specialty text NOT NULL CHECK(specialty IN ('skin','eecp','physio')),patient_id uuid NOT NULL REFERENCES hospital_patients(id),package_id uuid REFERENCES hospital_specialty_billing_packages(id),invoice_no text NOT NULL,amount numeric(14,2) NOT NULL DEFAULT 0 CHECK(amount>=0),status text NOT NULL DEFAULT 'unpaid',issued_at timestamptz NOT NULL DEFAULT now(),paid_at timestamptz,UNIQUE(tenant_id,invoice_no));
CREATE TABLE IF NOT EXISTS hospital_specialty_portal_profiles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),specialty text NOT NULL CHECK(specialty IN ('skin','eecp','physio')),patient_id uuid NOT NULL REFERENCES hospital_patients(id),preferences jsonb NOT NULL DEFAULT '{}'::jsonb,consent_at timestamptz,UNIQUE(tenant_id,specialty,patient_id));
CREATE INDEX IF NOT EXISTS idx_specialty_appt_tenant_time ON hospital_specialty_appointments(tenant_id,specialty,starts_at);
CREATE INDEX IF NOT EXISTS idx_specialty_invoice_tenant ON hospital_specialty_invoices(tenant_id,specialty,status);
